import unreal, json
world=unreal.EditorLevelLibrary.get_game_world()
actors=unreal.GameplayStatics.get_all_actors_of_class(world, unreal.Actor)
for a in actors:
    if 'BP_ChiR24_LockedDoor_C' in a.get_class().get_name():
        print(json.dumps({'hasKey': bool(a.get_editor_property('HasKey')), 'isOpen': bool(a.get_editor_property('IsOpen'))}))
